$ec_lang['cs_notes_1_term']='Njia';
$ec_lang['cs_notes_1_def']='Njia ya mtiririko wa ndani-nje inakadiri upotevu kwa kupima mtiririko mwanzoni na mwishoni mwa sehemu ya mfereji: Q<sub>loss</sub> = Q<sub>in</sub> − Q<sub>out</sub>. Ufanisi wa usafirishaji E<sub>c</sub> = Q<sub>out</sub> / Q<sub>in</sub>. Kiasi cha kila mwaka kinachukulia uendeshaji wa mtiririko kamili bila kukoma; upotevu halisi ni mdogo zaidi kwa mifereji ya msimu au yenye mtiririko mdogo.';
